import test from "node:test";
import assert from "node:assert/strict";
import { groupBy } from "./solution.mjs";

test("duplicate keys and stable order", () => {
  const items = [{ k: "a", n: 1 }, { k: "b", n: 2 }, { k: "a", n: 3 }];
  assert.deepEqual(groupBy(items, "k"), {
    a: [{ k: "a", n: 1 }, { k: "a", n: 3 }],
    b: [{ k: "b", n: 2 }],
  });
});
test("empty input", () => assert.deepEqual(groupBy([], "k"), {}));
